testbench_sv:
`timescale 1ns/1ps
module tb;
  reg clk, reset, serial_in;
  wire [3:0] q;

  shift_reg4 dut (.clk(clk), .reset(reset), .serial_in(serial_in), .q(q));

  initial clk = 0;
  always #5 clk = ~clk;

  initial begin
    #10000 $display("##TIMEOUT");
    $finish;
  end

  // Every input change happens only right after a settled "#1" following an
  // edge, never bare against a bare @(posedge clk). Setting an input in the
  // same simulation instant as the edge that samples it is a race — whether
  // the DUT's always block sees the old or new value is simulator-defined,
  // and earlier drafts of this testbench hit exactly that race.
  initial begin
    reset = 1; serial_in = 0;
    @(posedge clk); #1;
    if (q === 4'b0000) $display("##TEST T1 PASS exp=0000 got=%04b", q);
    else $display("##TEST T1 FAIL exp=0000 got=%04b", q);

    reset = 0; serial_in = 1;
    @(posedge clk); #1;
    if (q === 4'b0001) $display("##TEST T2 PASS exp=0001 got=%04b", q);
    else $display("##TEST T2 FAIL exp=0001 got=%04b", q);

    serial_in = 0;
    @(posedge clk); #1;

    serial_in = 1;
    @(posedge clk); #1;

    serial_in = 1;
    @(posedge clk); #1;
    if (q === 4'b1011) $display("##TEST T3 PASS exp=1011 got=%04b", q);
    else $display("##TEST T3 FAIL exp=1011 got=%04b", q);

    serial_in = 0;
    @(posedge clk); #1;
    if (q === 4'b0110) $display("##TEST T4 PASS exp=0110 got=%04b", q);
    else $display("##TEST T4 FAIL exp=0110 got=%04b", q);

    serial_in = 0;
    repeat (4) @(posedge clk);
    #1;
    if (q === 4'b0000) $display("##TEST T5 PASS exp=0000 got=%04b", q);
    else $display("##TEST T5 FAIL exp=0000 got=%04b", q);

    serial_in = 1;
    @(posedge clk); #1;

    reset = 1;
    #1;
    if (q === 4'b0001) $display("##TEST T6 PASS exp=0001 got=%04b", q);
    else $display("##TEST T6 FAIL exp=0001 got=%04b", q);
    reset = 0;

    $display("##DONE");
    $finish;
  end
endmodule

reference_sv:
module shift_reg4 (
    input  logic       clk,
    input  logic       reset,
    input  logic       serial_in,
    output logic [3:0] q
);
    always @(posedge clk) begin
        if (reset)
            q <= 4'b0000;
        else
            q <= {q[2:0], serial_in};
    end
endmodule
